source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            comp = []
            while stack:
                x,y = stack.pop()
                comp.append((x,y))
                for dx in (-1,0,1):
                    for dy in (-1,0,1):
                        q=(x+dx,y+dy)
                        if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 2 and q not in seen:
                            seen.add(q); stack.append(q)
            if len(comp) == 4:
                rs=[x for x,y in comp]; cs=[y for x,y in comp]
                cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
                if set(comp) == {(cr-1,cc),(cr,cc-1),(cr,cc+1),(cr+1,cc)}:
                    centers.append((cr,cc))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r == rr:
                for y in range(min(c,cc)+2, max(c,cc)-1):
                    if out[r][y] == 0: out[r][y] = 1
            elif c == cc:
                for x in range(min(r,rr)+2, max(r,rr)-1):
                    if out[x][c] == 0: out[x][c] = 1
    return out
